import fs from 'node:fs';import {DatabaseSync} from 'node:sqlite';import {pathToFileURL} from 'node:url';
const p=JSON.parse(process.argv[2]);const {BuyerTaskStore}=await import(pathToFileURL(p.bundle).href);const db=new DatabaseSync(p.db);db.exec('PRAGMA busy_timeout=2000');const store=new BuyerTaskStore({db,principalId:'buyer',now:()=>p.now});fs.writeFileSync(p.ready,'ready');const end=Date.now()+5000;while(!fs.existsSync(p.go)){if(Date.now()>end)throw Error('barrier timeout');await new Promise(r=>setTimeout(r,5));}try{const result=store.beginToolCall(p.task,'shared-call','update_buyer_task_constraints',{task_id:p.task,constraints:{}});process.stdout.write(JSON.stringify({result:result.kind}));}catch(e){process.stdout.write(JSON.stringify({error:String(e)}));}finally{db.close();}
